function exportBookings(bookings) {
    const quote = (value)=>'"'.concat(value.replaceAll('"', '""'), '"');
    const rows = [
        [
            'Full name',
            'Phone number',
            'Room choice',
            'Group',
            'Email',
            'Status'
        ],
        ...bookings.map((item)=>[
                item.memberName,
                item.memberPhone,
                item.room,
                item.memberGroup,
                item.memberEmail,
                item.status
            ])
    ];
    const csv = '\uFEFF' + rows.map((row)=>row.map((value)=>quote(String(value))).join(',')).join('\r\n');
    const url = URL.createObjectURL(new Blob([
        csv
    ], {
        type: 'text/csv;charset=utf-8'
    }));
    const link = document.createElement('a');
    link.href = url;
    link.download = "city-mega-church-camp-bookings-".concat(new Date().toISOString().slice(0, 10), ".csv");
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
}
